const body = $input.first().json.body || {};
for (const f of ['tenant_slug', 'entity_type', 'entity_id']) {
  if (!body[f]) throw new Error(`${f} is required`);
}
const validTypes = ['contact', 'lead', 'appointment'];
if (!validTypes.includes(body.entity_type)) {
  throw new Error(`entity_type must be one of: ${validTypes.join(', ')}`);
}
return [{
  json: {
    tenant_slug: String(body.tenant_slug).trim(),
    entity_type: body.entity_type,
    entity_id: body.entity_id,
    crm_provider: body.crm_provider ? String(body.crm_provider).trim() : 'generic_webhook',
  }
}];

